const powersOfTen = [];
for(let i = 0; i < 632; i++) {
  powersOfTen.push(10 ** (i - 323));
}

// Lots of constants
const FLUSH_FIVE = 0;
const FLUSH_HOUSE = 1;
const FIVE_OF_A_KIND = 2;
const STRAIGHT_FLUSH = 3;
const FOUR_OF_A_KIND = 4;
