const SELL_VALUE = 4;

const LEVEL = 0;
const PLANETS = 1;
const PLAYED = 2;
const PLAYED_THIS_ROUND = 3;

const cardValues = [2, 3, 4, 5, 6, 7, 8, 9, 10, 10, 10, 10, 11];

function bigAdd(a, b) {
  if(b[1] > 308) {
    return b;
  }
  return [
    a / powersOfTen[b[1] + 323] + b[0],
    b[1]
  ];
}

function bigTimes(a, b) {
  const tempM = a * b[0];

  if(tempM > 1e13) {
    const tempE = Math.floor(Math.log10(Math.abs(tempM))) + 13;

    return [
      tempM / powersOfTen[tempE + 323],
      b[1] + tempE
    ];
  }
  else {
    return [
      tempM,
      b[1]
    ];
  }
}

function bigBigAdd(a, b) {
  if(b[1] > a[1]) {
    const diff = b[1] - a[1];
    if(diff >= 309) {
      return b;
    }
    return [
      a[0] / powersOfTen[diff + 323] + b[0],
      b[1]
    ];
  }
  else {
    const diff = a[1] - b[1];
    if(diff >= 309) {
      return a;
    }
    return [
      b[0] / powersOfTen[diff + 323] + a[0],
      a[1]
    ];
  }
}

function bigBigTimes(a, b) {
  return [
    a[0] * b[0],
    a[1] + b[1]
  ];
}

function normalizeBig(b) {
  const tempE = Math.floor(Math.log10(Math.abs(b[0])));

  return [
    b[0] / powersOfTen[tempE + 323],
    b[1] + tempE
  ];
}

/*
brute-force order of operations:

- compileJokers()
- all combinations of joker order
  - compileJokerOrder()
- all combinations of cards played
  - compileCards()
- all combinations of cards played order
  - simulate()
*/

// svelte-ignore perf_avoid_nested_class (Each calculation needs isolated mutable hand-value tables.)
class Hand {
  hands = [];
  jokersExtraValue = [];
  jokerRarities = [];

  randomMode = 0;
  chips = 0;
  mult = [1, 0]; // big-float

  chanceMultiplier = 1;

  FourFingers = false; // straights/flushes with 4 cards
  Shortcut = false; // straights can skip numbers
  Pareidolia = false; // all cards are faces
  SmearedJoker = false; // hearts = diamonds, clubs = spades
  Splash = false; // every card is counted in scoring

  hasVampire = false;
  Vampire = false;
  BaseballCard = 0;

  RaisedFist = false;

  MidasMaskas = false;

  compiledValues = [];

  handType = 11;
  involvedCards = [];

  hasPair = false;
  hasTwoPair = false;
  hasThreeOfAKind = false;
  hasFourOfAKind = false;
  hasStraight = false;
  hasFlush = false;

  compiledChips = 0;
  compiledMult = [1, 0];

  compiledInHandPlusMult = [0, 0];
  compiledInHandTimesMult = [1, 0];
  cardCast = [];
  cardExtraExtraChips = [];

  actualCardsInHand = [];

  firstHand = true;
  earnedMoney = 0;

  constructor({
    cards = [],
    cardsInHand = [],
    jokers = [],
    hands = false,
    TheFlint = false,
    TheEye = false,
    PlasmaDeck = false,
    Observatory = false
  } = {}) {
    this.cards = cards;
    this.cardsInHand = cardsInHand;
    this.jokers = jokers;
    if(hands) {
      this.hands = hands;

      this.firstHand = true;
      for(let i = 0; i < this.hands.length; i++) {
        if(this.hands[i][PLAYED_THIS_ROUND]) {
          this.firstHand = false;
          break;
        }
      }
    }
    else {
      for(let i = 0; i < handChips.length; i++) {
        this.hands.push([
          1, // level
          0, // planets
          0, // played
          0, // played this round
        ]);
      }

      this.firstHand = true;
    }
    this.TheFlint = TheFlint;
    this.TheEye = TheEye;
    this.PlasmaDeck = PlasmaDeck;
    this.Observatory = Observatory;
  }

  triggerJoker(joker, j) {
    if(joker[JOKER_DISABLED]) return;

    if(joker[EDITION] === FOIL) {
      this.chips += 50;
    }
    else if(joker[EDITION] === HOLOGRAPHIC) {
      this.mult = bigAdd(10, this.mult);
    }

    switch(joker[JOKER]) {
      case 0:
        // Joker
        this.mult = bigAdd(4, this.mult);
        break;
      case 2:
        // Jolly Joker
        if(this.hasPair) {
          this.mult = bigAdd(8, this.mult);
        }
        break;
      case 3:
        // Zany Joker
