  let chipsRemaining = $derived(
    progress?.target != null && progress?.current != null ? Math.max(0, progress.target - progress.current) : null,
  );
  let blindChoices = $derived(
    String(latest.phase || "").toUpperCase() === "BLIND_SELECT"
      ? Object.entries(latest.blinds || {}).map(([id, blind]) => ({ id, ...blind })) : [],
  );
  let activeAction = $derived(actions[activeFrame?.index ?? -1] || null);
  let previousState = $derived(replay.inputs[activeFrame?.index] || initialState);
  let selectedIndices = $derived(
    activeAction && ["play", "discard", "use"].includes(activeAction.method) && Array.isArray(activeAction.params?.cards)
      ? activeAction.params.cards
      : [],
  );
  // A frame is the state *after* its corresponding action.  In particular,
  // the final play of a blind can legitimately result in SHOP, where the
  // game has no hand.  Keep the input cards visible for that action, but do
  // not present them as cards still held in the resulting state.
  let actionUsesInputHand = $derived(
    selectedIndices.length > 0 && previousState && ["play", "discard", "use"].includes(activeAction?.method),
  );
  let handForAction = $derived(actionUsesInputHand ? area(previousState, "hand") : hand);
  let handLabel = $derived(
    actionUsesInputHand
      ? `${activeAction.method.toUpperCase()} INPUT · PRE-${String(latest.phase || "HAND").toUpperCase()} STATE`
      : latest.phase === "shop" ? "HAND · NO HAND IN SHOP"
      : "HAND",
  );
  // Balatro advances ante_num immediately after the boss is beaten, before
  // the post-boss shop opens.  Calling this out avoids making the correct
  // next-ante value look like an off-by-one error next to the prior round.
  let enteredNewAnte = $derived(
    latest.phase === "shop"
      && Number.isFinite(Number(previousState?.ante))
      && Number(latest.ante) === Number(previousState.ante) + 1,
  );
  let anteLabel = $derived(
    latest.ante != null ? `ANTE ${latest.ante}${enteredNewAnte ? " · NEW ANTE (BOSS CLEARED)" : ""}` : "",
  );
  let actionTarget = $derived(
    activeAction?.method === "use" ? activeAction.params?.consumable
      : activeAction?.method === "buy" ? activeAction.params?.card ?? activeAction.params?.voucher ?? activeAction.params?.pack
      : activeAction?.method === "sell" ? activeAction.params?.joker ?? activeAction.params?.consumable
      : null,
  );
  let actionTargetName = $derived(
    activeAction?.method === "use" ? "consumable"
      : activeAction?.method === "buy" ? (activeAction.params?.voucher != null ? "voucher" : activeAction.params?.pack != null ? "pack" : "card")
      : activeAction?.method === "sell" ? (activeAction.params?.joker != null ? "joker" : "consumable")
      : "",
  );
  let actionCards = $derived(
    activeAction && Array.isArray(activeAction.params?.cards) ? activeAction.params.cards : [],
  );
  let actionConsumable = $derived(
    activeAction?.method === "use" && Number.isInteger(actionTarget) && previousState
      ? area(previousState, "consumables")[actionTarget] || null
      : null,
  );
  let hand = $derived(area(latest, "hand"));
  let deck = $derived(area(latest, "deck"));
  let discard = $derived(area(latest, "discard"));
  let deckCount = $derived(latest.deck_left ?? (deck.length > 0 ? deck.length : null));
  let discardCount = $derived(
    latest.discard_count ?? (discard.length > 0 ? discard.length : null),
  );
  let phase = $derived(String(latest.phase || "").toUpperCase());
  let shopItems = $derived(phase === "SHOP" ? area(latest, "shop") : []);
  let packOffers = $derived(phase === "SHOP" ? area(latest, "packs") : []);
  let packChoices = $derived(phase === "PACK" || phase === "SMODS_BOOSTER_OPENED" ? area(latest, "pack") : []);
  let inspector = $state("");
  let inventoryFocus = $state("");
  let flatFrames = $derived(groups.flatMap((group, groupIndex) => group.frames.map((frame, frameIndex) => ({ ...frame, groupIndex, frameIndex }))));
  let framePosition = $derived(Math.max(0, flatFrames.findIndex(frame => frame.index === activeFrame?.index)));

  function seekFrame(position) {
    const frame = flatFrames[Math.max(0, Math.min(flatFrames.length - 1, Number(position)))];
    if (frame) { activeGroupIndex = frame.groupIndex; activeFrameIndex = frame.frameIndex; }
  }
  let jokers = $derived(area(latest, "jokers"));
  let consumables = $derived(area(latest, "consumables"));
  let consumablesForView = $derived(
    activeAction?.method === "use" && actionConsumable
      ? area(previousState, "consumables")
      : consumables,
  );
  let vouchers = $derived(area(latest, "vouchers"));
  let ownedVouchers = $derived(area(latest, "owned_vouchers"));
  let recordedHands = $derived([...new Set([
    ...Object.keys(latest.hand_values || {}), ...Object.keys(latest.hand_stats || {}),
  ])].map((name) => {
    const values = latest.hand_values?.[name] || [];
    const stats = latest.hand_stats?.[name] || [];
    return { name, level: values[0] ?? stats[0], chips: values[1], mult: values[2], played: stats[1], round: stats[2] };
  }));
  let handValues = $derived(
    calcState?.hand_values && typeof calcState.hand_values === "object" ? calcState.hand_values : {},
  );
  let latestReward = $derived(Array.isArray(rewardEvents) ? rewardEvents.at(-1) : null);
  let skipResult = $derived.by(() => {
    if (activeAction?.method !== "skip") return null;
    // New harnesses attach this directly to the resulting state delta.
    if (latest?.action_result?.method === "skip") return latest.action_result;
    // Fall back to deriving it for older trajectories.
    const skipped = previousState ? Object.entries(previousState.blinds || {})
      .map(([id, blind]) => ({ id, ...(blind || {}) }))
      .find((blind) => String(blind.status || "").toUpperCase() === "SELECT") : null;
    const next = selectedBlind(latest);
    if (!skipped || String(latest.blinds?.[skipped.id]?.status || "").toUpperCase() !== "SKIPPED") return null;
    return {
      method: "skip",
      skipped: { id: skipped.id, name: blindLabel(skipped), type: skipped.type },
      tag: skipped.tag,
      tag_effect: skipped.tag_effect,
      next: next ? { id: next.id, name: blindLabel(next), type: next.type, score: next.score, effect: next.effect } : null,
    };
  });

  const viewerId = $props.id();
  let calcDraft = $state({ key: null, selected: [], values: {}, options: {} });
  let calcOutput = $state(null);
  let openJoker = $state(null);
  let calcState = $derived(actionUsesInputHand ? previousState : latest);
  let calcKey = $derived(`${sample?.sample_id || sample?.id || "sample"}:${activeFrame?.index ?? -1}:${JSON.stringify(calcState)}`);
  let calcSelected = $derived(calcDraft.key === calcKey ? calcDraft.selected : activeAction?.method === "play" ? [...selectedIndices] : []);
  let calcValues = $derived(calcDraft.key === calcKey ? calcDraft.values : {});
  let calcOptions = $derived(calcDraft.key === calcKey ? calcDraft.options : calculatorDefaults(calcState || {}));
  let calcJokerInputs = $derived(calculatorJokers(calcState || {}, calcValues));
  let canCalculate = $derived(["HAND", "SELECTING_HAND"].includes(String(calcState?.phase || "").toUpperCase()) && handForAction.length > 0);
  let recordedPlay = $derived(activeAction?.method === "play" ? latest.play_commit : null);
  let calcResult = $derived.by(() => {
    if (calcOutput?.key === calcKey) return calcOutput.result;
    if (activeAction?.method === "play" && canCalculate && calcSelected.length) {
      return calculateHand(calcState, calcSelected, calcValues, calcOptions);
    }
    return null;
  });

  function updateCalculator(change) {
    calcDraft = { key: calcKey, selected: [...calcSelected], values: { ...calcValues }, options: { ...calcOptions }, ...change };
    calcOutput = null;
  }

  function toggleCalculatorCard(index) {
    if (!canCalculate) return;
    const next = calcSelected.includes(index) ? calcSelected.filter(i => i !== index) : calcSelected.length < 5 ? [...calcSelected, index] : calcSelected;
    updateCalculator({ selected: next });
  }

  function runCalculator() {
    calcOutput = { key: calcKey, result: calculateHand(calcState, calcSelected, calcValues, calcOptions) };
  }

  function selectGroup(index) {
    activeGroupIndex = index;
    activeFrameIndex = 0;
  }
</script>

{#snippet finish(card)}
  {#if modifierValue(card, "edition") && modifierValue(card, "edition") !== "base"}
    <span class="finish-layer" aria-hidden="true"></span>
  {/if}
{/snippet}

{#snippet badges(card)}
  {@const modifiers = modifierBadges(card)}
  {#if modifiers.length}
    <div class="modifier-badges" aria-label="Card modifiers">
      {#each modifiers as badge}
        <span class="modifier-badge" data-kind={badge.kind} data-value={badge.value}>{badge.label}</span>
      {/each}
    </div>
  {/if}
{/snippet}

{#snippet spriteArt(card, joker = false)}
  {@const visual = spriteVisual(card, joker)}
  {#if visual}
    <div class="sprite-art" data-edition={modifierValue(card, "edition")} style={visual.mask} role="img" aria-label={joker ? [itemName(card), ...modifierBadges(card).map((badge) => badge.label)].join(" · ") : cardTitle(card)}>
      {#each visual.layers as layer}<span class="sprite-layer" data-layer={layer.kind} style={layer.style} aria-hidden="true"></span>{/each}
    </div>
  {/if}
{/snippet}

{#snippet jokerRack(items)}
  <div class="section-label"><span>JOKERS</span><small>{latest.jokers?.slots ?? items.length + " recorded"} · hover, focus, or tap for info</small></div>
  <div class="joker-rack">
    {#each items as joker, index}
      {@const tooltipId = `${viewerId}-joker-${index}`}
      <div class="joker-slot" class:open={openJoker?.key === calcKey && openJoker.index === index}>
        <button type="button" class="joker-trigger" aria-describedby={tooltipId} aria-label={`Info: ${itemName(joker)}`} onclick={() => { openJoker = openJoker?.key === calcKey && openJoker.index === index ? null : { key: calcKey, index }; }} onkeydown={(event) => { if (event.key === "Escape") { openJoker = null; event.currentTarget.blur(); } }}>
          <span class="joker-art">{#if spriteVisual(joker, true)}{@render spriteArt(joker, true)}{:else}<span class="unknown-joker">★</span>{/if}</span>
          <span class="joker-name">{itemName(joker)}</span>
        </button>
        {@render badges(joker)}
        <div class="joker-tooltip" id={tooltipId} role="tooltip">
          <strong>{itemName(joker)}</strong>
          <p>{joker.effect || "Effect not recorded in this trajectory."}</p>
          {#if recordedJokerTarget(joker)}<p class="edition-info">Round target: {recordedJokerTarget(joker).label}<small>{recordedJokerTarget(joker).source}</small></p>{/if}
          {@render badges(joker)}
          {#if modifierValue(joker, "edition") === "foil"}<p class="edition-info">Foil: +50 Chips</p>{/if}
          {#if ["holo", "holographic"].includes(modifierValue(joker, "edition"))}<p class="edition-info">Holographic: +10 Mult</p>{/if}
          {#if modifierValue(joker, "edition") === "polychrome"}<p class="edition-info">Polychrome: ×1.5 Mult</p>{/if}
          {#if joker.sell != null}<small>Sell value: ${joker.sell}</small>{/if}
          <small>Recorded joker {index + 1} · left-to-right scoring order</small>
        </div>
      </div>
    {:else}<div class="empty-section">No jokers in this frame.</div>{/each}
  </div>
{/snippet}

{#snippet inventoryCard(item, index, kind = "item")}
  {@const isJoker = String(typeof item === "string" ? item : item.id || item.key || "").startsWith("j_")}
  {@const title = cardInfo(item).suit ? cardTitle(item) : itemName(item)}
  <details class="inventory-card" data-kind={kind}>
    <summary>
      <span class="inventory-art">{#if spriteVisual(item, isJoker)}{@render spriteArt(item, isJoker)}{:else}<span class="inventory-symbol">{kind === "pack" ? "✦" : kind === "voucher" ? "◆" : "☾"}</span>{/if}</span>
      <span class="inventory-name">{title}</span>
      <small>#{index}{item.cost != null ? " · $" + item.cost : ""}{kind === "owned" ? " · owned" : ""}</small>
      {@render badges(item)}
    </summary>
    <div class="inventory-description"><b>{title}</b><p>{item.effect || "Effect not recorded in this trajectory."}</p>{#if item.sell != null}<small>Sell value: {"$" + item.sell}</small>{/if}<details><summary>Recorded data</summary><pre>{JSON.stringify(item, null, 2)}</pre></details></div>
  </details>
{/snippet}

<section class="balatro-viewer" data-trajectory-viewer="balatro" style={Object.entries(CARD_ATLASES).map(([name, data]) => `--atlas-${name}:url('${data}')`).join(";")}>

  <header class="viewer-header">
    <div class="replay-brand"><b>BALATRO</b><small>TRAJECTORY REPLAY · READ ONLY</small></div>
    <div class="replay-meta">{states.length} recorded moves · {groups.length} phase groups{#if replay.finalAnte != null} · Final ante {replay.finalAnte}{/if}</div>
    <span class="run-badge">{latest.phase || run?.status || "RUN"}</span>
  </header>
  {#if activeGroup}
    {#if replay.segments < replay.expectedSegments}<p class="replay-notice">Partial replay: {replay.segments} of {replay.expectedSegments} game segments available.</p>{/if}
    {#if replay.missingResults}<p class="replay-notice">{replay.missingResults} move result{replay.missingResults === 1 ? " was" : "s were"} not saved. Showing recorded states only.</p>{/if}
    <nav class="blind-strip" aria-label="Ante, round, and blind">
      {#each groups as group, index}
        <button aria-current={index === activeGroupIndex ? "step" : undefined} class:active={index === activeGroupIndex} class="blind-tab" onclick={() => selectGroup(index)}>
          <span class="tab-index">{String(index + 1).padStart(2, "0")}</span>
          <span><b>{group.blind}</b><small>{group.ante != null ? `ante ${group.ante}` : ""}{group.round != null ? ` · round ${group.round}` : ""}</small></span>
        </button>
      {/each}
    </nav>


      <div class="turn-strip replay-controls" aria-label="Turns in selected blind">
        <button type="button" onclick={() => seekFrame(0)}>Start</button>
        <button type="button" aria-label="Previous frame" disabled={framePosition === 0} onclick={() => seekFrame(framePosition - 1)}>◀</button>
        <span>{activeGroup.frames.length} turns</span>
        {#each activeGroup.frames as frame, index}
          <button class:active={index === activeFrameIndex} class="turn-dot" title={frame.index < 0 ? "Initial state · before any action" : `turn ${replay.turns[frame.index]}`} onclick={() => (activeFrameIndex = index)}>{frame.index < 0 ? "S" : replay.turns[frame.index]}</button>
        {/each}
        <button type="button" aria-label="Next frame" disabled={framePosition >= flatFrames.length - 1} onclick={() => seekFrame(framePosition + 1)}>▶</button>
        <button type="button" onclick={() => seekFrame(flatFrames.length - 1)}>Last recorded frame</button>
      </div>
    <div class="game-layout">
      <aside class="game-hud" aria-label="Recorded game status">
        <div class="blind-hud">
          <h3>{String(progress?.label || latest.phase || "RUN").replaceAll("_", " ")}</h3>
          {#if latest.blind?.effect && progress && !progress.pending}<p>{latest.blind.effect}</p>{/if}
          {#if progress}
            <div class="target"><span class="blind-chip" aria-hidden="true">✹</span><div><small>CHIPS REQUIRED TO CLEAR</small><strong>{chips(progress.target)}</strong></div></div>
          {:else}<p class="chip-note">No active blind score in this phase.</p>{/if}
        </div>
        {#if progress}
          <div class="round-score"><small>CHIPS SCORED · THIS BLIND</small><strong>{chips(progress.current)}</strong></div>
          <div class="remaining-score"><small>CHIPS STILL NEEDED</small><strong>{chips(chipsRemaining)}</strong></div>
          <details class="score-info"><summary>About this target</summary><p>{progress.pending ? "Blind not started. Chips start at 0 when you select it." : "Chips are cumulative within this blind and reset for the next blind."} Each ante has separate Small, Big, and Boss targets.</p></details>
        {/if}
        <div class="hud-calculation" aria-live="polite">
          {#if recordedPlay}
            <div class="recorded-score"><small>ACTUAL PLAY · RECORDED</small><b>{recordedPlay.hand || "Played hand"}</b><strong>{chips(number(recordedPlay.score))} chips</strong></div>
          {/if}
          <small>UI CALCULATOR · ESTIMATE</small>
          <b>{calcResult && !calcResult.error ? calcResult.low.hand : "Select cards to calculate"}</b>
          <div class="score-factors"><span class="chips-factor">{calcResult && !calcResult.error ? bigLabel(calcResult.low.chips) : "—"}</span><b>×</b><span class="mult-factor">{calcResult && !calcResult.error ? bigLabel(calcResult.low.mult) : "—"}</span></div>
          {#if calcResult && !calcResult.error}<strong>{bigLabel(calcResult.low.score)}{calcResult.range ? " – " + bigLabel(calcResult.high.score) : ""}</strong>{/if}
          {#if calcResult?.error}<button class="calculator-input-link" onclick={() => inspector = "calculator"}>Estimate needs inputs · view details</button>{/if}
        </div>
        <div class="resource-grid">
          <div class="hands-resource"><small>Hands left</small><strong>{progress && !progress.pending ? latest.blind?.hands ?? "—" : "—"}</strong></div>
          <div class="discards-resource"><small>Discards left</small><strong>{progress && !progress.pending ? latest.blind?.discards ?? "—" : "—"}</strong></div>
          <div class="money-resource"><small>Cash</small><strong>{latest.money != null ? "$" + latest.money : "—"}</strong></div>
          <div><small>Current ante</small><strong>{latest.ante ?? "—"}<em>/8</em></strong></div>
          <div><small>Round</small><strong>{latest.round ?? "—"}</strong></div>
        </div>
        {#if enteredNewAnte}<p class="ante-note">{anteLabel}</p>{/if}
        <div class="hud-buttons">
          <button class="run-info-button" aria-expanded={inspector === "inventory"} onclick={() => inspector = inspector === "inventory" ? "" : "inventory"}>Run info</button>
          <button class="settings-button" aria-expanded={inspector === "calculator"} onclick={() => inspector = inspector === "calculator" ? "" : "calculator"}>Calculator</button>
          <button class="trace-button" aria-expanded={inspector === "trace"} onclick={() => inspector = inspector === "trace" ? "" : "trace"}>Trace & rewards</button>
        </div>
      </aside>
      <div class="game-table">
        <div class="top-racks">
          <div class="jokers-zone">{@render jokerRack(jokers)}</div>
          <div class="consumable-zone">
            <div class="section-label"><span>CONSUMABLES</span><small>{latest.consumables?.slots ?? consumables.length + " recorded"}</small></div>
            <div class="mini-rack">{#each consumables as item, index}{@render inventoryCard(item, index, "consumable")}{:else}<span class="empty-slot">No consumables</span>{/each}</div>
          </div>
        </div>
        <div class="phase-stage" data-phase={phase}>
      {#if activeAction}
        <div class:action-play={activeAction.method === "play"} class:action-discard={activeAction.method === "discard"} class:action-use={activeAction.method === "use"} class="action-banner">
          <span class="action-method">{activeAction.method.replaceAll("_", " ")}</span>
          {#if actionCards.length}<span>cards [{actionCards.join(", ")}]</span>{/if}
          {#if actionTarget != null}<span>{actionTargetName} {actionTarget}{#if actionConsumable} · {itemName(actionConsumable)}{/if}</span>{/if}
          {#if activeAction.method === "skip"}<span>skip blind · take its tag</span>{/if}
          {#if activeAction.method === "next_round"}<span>leave shop · choose next blind</span>{/if}
        </div>
        {#if skipResult}
          <div class="skip-result">
            <div class="skip-result-title"><span>TAG TAKEN · IN-GAME SKIP REWARD</span><b>{skipResult.tag || "Tag not recorded"}</b></div>
            <div class="skip-result-grid">
              <div><small>SKIPPED</small><strong>{blindLabel(skipResult.skipped)}</strong></div>
              <div><small>EFFECT / WHEN IT APPLIES</small><strong>{skipResult.tag_effect || "Effect not recorded in this trajectory."}</strong></div>
              {#if skipResult.next}<div><small>NEXT BLIND</small><strong>{blindLabel(skipResult.next)}{#if skipResult.next.score != null} · {chips(skipResult.next.score)} chips required{/if}</strong></div>{/if}
            </div>
          </div>
        {/if}
      {/if}

        {#if blindChoices.length}
          <div class="section-label"><span>BLIND SELECTION · TARGETS & SKIP REWARDS</span></div>
          <div class="blind-choices">
            {#each blindChoices as blind}
              {@const status = String(blind.status || "UNKNOWN").toUpperCase()}
              {@const boss = String(blind.type || blind.id).toUpperCase() === "BOSS"}
              <article class:offered={status === "SELECT"} class="blind-choice">
                <div class="choice-heading"><b>{blindLabel(blind)}</b><small>{status === "SELECT" ? "AVAILABLE NOW" : status}</small></div>
                <p class="choice-target">Clear target: <strong>{chips(blind.score)} chips</strong></p>
                {#if blind.effect}<p>{blind.effect}</p>{/if}
                {#if boss}
                  <div class="tag-offer"><b>Cannot skip the Boss Blind</b><p>No skip reward.</p></div>
                {:else}
                  <div class="tag-offer"><small>{status === "SKIPPED" ? "TAG TAKEN" : status === "DEFEATED" ? "SKIP OFFER · NOT TAKEN" : "SKIP TO RECEIVE"}</small><b>{blind.tag || "Tag not recorded"}</b><p>{blind.tag_effect || "Effect not recorded in this trajectory."}</p></div>
                {/if}
              </article>
            {/each}
          </div>
          <p class="chip-note">Skipping takes the tag instead of playing that blind. The description above states when its benefit applies; this is an in-game reward, not the training reward.</p>
        {/if}


          {#if phase === "SHOP"}
            <div class="phase-heading"><h4>SHOP</h4><span>Reroll {latest.reroll_cost != null ? "$" + latest.reroll_cost : "cost not recorded"}</span></div>
            <div class="shop-layout">
              <div><div class="section-label"><span>CARDS FOR SALE</span></div><div class="offer-rack">{#each shopItems as item, index}{@render inventoryCard(item, index, "shop")}{:else}<p class="empty-slot">No cards recorded.</p>{/each}</div></div>
              <div><div class="section-label"><span>VOUCHERS & BOOSTER PACKS</span></div><div class="offer-rack">{#each vouchers as item, index}{@render inventoryCard(item, index, "voucher")}{/each}{#each packOffers as item, index}{@render inventoryCard(item, index, "pack")}{/each}</div></div>
            </div>
          {:else if phase === "PACK" || phase === "SMODS_BOOSTER_OPENED"}
            <div class="phase-heading"><h4>BOOSTER PACK</h4><span>{packChoices.length} recorded choices</span></div>
            <div class="offer-rack pack-rack">{#each packChoices as item, index}{@render inventoryCard(item, index, "choice")}{:else}<p class="empty-slot">No pack choices recorded.</p>{/each}</div>
          {:else if phase === "GAME_OVER"}
            <div class="end-state"><h4>GAME OVER</h4><p>Recorded terminal state · Ante {latest.ante ?? "—"}, round {latest.round ?? "—"}</p></div>
          {:else if !blindChoices.length && !activeAction}
            <div class="table-watermark">BALATRO<small>{progress ? "Score the blind to advance" : "Recorded game state"}</small></div>
          {/if}
        </div>
        <div class="hand-zone" class:historical={actionUsesInputHand}>
        <div class="section-label"><span>{handLabel}</span><small>{handForAction.length} cards</small></div>
        {#if selectedIndices.length}
          <div class="selection-note"><span class="selection-dot"></span>{activeAction.method} selected cards <b>[{selectedIndices.join(", ")}]</b></div>
        {/if}
        {#if handForAction.length}
          <div class="hand">
            {#each handForAction as card, index (`${activeFrame?.index}-${index}-${cardTitle(card)}`)}
              {@const info = cardInfo(card)}
              {@const isSelected = calcSelected.includes(index)}
              {@const wasDiscarded = activeAction?.method === "discard" && selectedIndices.includes(index)}
              {@const hasArt = spriteVisual(card) != null}
              <div class="card-slot" class:dimmed={calcSelected.length > 0 ? !isSelected : activeAction?.method === "discard" && !wasDiscarded}>
                <button type="button" class:red={info.red} class:selected={isSelected} class:recorded-discard={wasDiscarded} class:has-art={hasArt} class="playing-card modifier-surface" data-edition={modifierValue(card, "edition")} data-enhancement={modifierValue(card, "enhancement")} title={cardTitle(card)} aria-label={`${wasDiscarded ? "Discarded this turn. " : ""}Select ${cardTitle(card)} for UI calculation`} aria-pressed={isSelected} disabled={!canCalculate} onclick={() => toggleCalculatorCard(index)}>
                  {#if hasArt}
                    {@render spriteArt(card)}
                  {:else}
                    {@render finish(card)}
                    <span class="corner"><b>{info.rank}</b><i>{info.suit}</i></span><strong>{info.suit || "·"}</strong>
                    {#if modifierValue(card, "seal")}<span class="wax-seal" data-seal={modifierValue(card, "seal")} aria-label={`${prettyModifier(modifierValue(card, "seal"))} Seal`}>✦</span>{/if}
                  {/if}
                  {#if isSelected}<span class="selected-mark">{calcSelected.indexOf(index) + 1}</span>{/if}
                  {#if wasDiscarded}<span class="discarded-mark" aria-hidden="true">✕</span>{/if}
                </button>
                <span class="card-caption">{modifierValue(card, "enhancement") === "stone" ? "Stone" : `${info.rank}${info.suit}`}</span>
                {@render badges(card)}
              </div>
            {/each}
          </div>
        {:else}<div class="empty-section">No hand data at this turn.</div>{/if}



          {#if actionUsesInputHand}<p class="historical-note">Historical action input. HUD and top inventory show the resulting state; calculation uses the pre-action cards and jokers.</p>{/if}
          <div class="table-actions">
            <div class="calculator-actions"><button type="button" class="calculate-button" disabled={!canCalculate || !calcSelected.length} onclick={() => { runCalculator(); if (calcOutput?.result?.error) inspector = "calculator"; }}>Calculate{calcSelected.length ? " (" + calcSelected.length + ")" : ""}</button><button type="button" disabled={!calcSelected.length} onclick={() => updateCalculator({ selected: [] })}>Clear</button></div>
            <small>UI only · never plays a hand</small>
            <button class="deck-peek" aria-label="Inspect deck" aria-expanded={inspector === "inventory" && inventoryFocus === "deck"} onclick={() => { inventoryFocus = "deck"; inspector = "inventory"; }}><span class="deck-back" aria-hidden="true">♠</span><span>DECK {deckCount ?? "—"}</span></button>
            <button class="discard-peek" aria-label="Inspect discard pile" aria-expanded={inspector === "inventory" && inventoryFocus === "discard"} onclick={() => { inventoryFocus = "discard"; inspector = "inventory"; }}>Discard pile: {discardCount ?? "—"}</button>
          </div>
        </div>
      </div>
    </div>
    <div class="inspector-panel" hidden={!inspector}>
      <div class="inspector-heading"><b>{inspector === "calculator" ? "HAND CALCULATOR" : inspector === "inventory" ? "RUN INFORMATION" : "TRACE INSPECTOR"}</b><button type="button" onclick={() => inspector = ""} aria-label="Close inspector">✕</button></div>
      <div class="inspector-content" hidden={inspector !== "calculator"}>
      <aside class="calculator-panel" aria-label="EFHIII hand calculator">
        <div class="calculator-title">HAND CALCULATOR <small>EFHIII scoring engine</small></div>
        <div class="calculator-score" aria-live="polite">
          {#if calcResult && !calcResult.error}
            <h4>{calcResult.low.hand}</h4>
            <strong>{bigLabel(calcResult.low.score)}{#if calcResult.range} – {bigLabel(calcResult.high.score)}{/if}</strong>
            <div class="score-factors"><span class="chips-factor">{bigLabel(calcResult.low.chips)}</span><b>×</b><span class="mult-factor">{bigLabel(calcResult.low.mult)}</span></div>
            <small>{calcResult.range ? "Worst–best outcome range; factors show the low outcome." : "Calculator result for the supplied inputs."}</small>
          {:else}<h4>Select a hand</h4><strong>—</strong><div class="score-factors"><span class="chips-factor">Chips</span><b>×</b><span class="mult-factor">Mult</span></div>{/if}
        </div>
        <p class="calculator-help">Click 1–5 cards in play order. Joker order stays as recorded. {actionUsesInputHand ? "Uses the pre-action hand, not the resulting shop/hand." : "Uses this frame's hand."}</p>
        <div class="calculator-actions"><button type="button" class="calculate-button" disabled={!canCalculate || !calcSelected.length} onclick={runCalculator}>Calculate {calcSelected.length ? `(${calcSelected.length})` : ""}</button><button type="button" onclick={() => updateCalculator({ selected: [] })}>Clear</button></div>
        {#if !canCalculate}<p class="calculator-help">Choose a hand/play frame to calculate. Selection, shop and pack frames are not playable hands.</p>{/if}
        {#if calcResult?.error}<p class="calculator-error" role="alert">{calcResult.error}</p>{/if}
        {#if calcJokerInputs.some(j => j.label || j.id == null)}
          <div class="section-label"><span>JOKER INPUTS</span></div>
          <p class="calculator-help">Same value inputs as the calculator. Blank means not recorded; enter the value from the joker's effect.</p>
          <div class="calculator-inputs">{#each calcJokerInputs as input}
            {#if input.id == null}<p class="calculator-error">{input.name}: unsupported by this calculator.</p>
            {:else if input.label}<label><span>{input.name}<small>{input.label}{input.automatic != null ? " · from trace" : " · required"}</small>{#if input.target}<small>Round target: {input.target.label} · {input.target.source}</small>{/if}</span><input type="number" step="any" aria-label={`${input.name}: ${input.label}`} value={input.value ?? ""} placeholder="Missing" oninput={(event) => updateCalculator({ values: { ...calcValues, [input.index]: event.currentTarget.value } })}/></label>{/if}
          {/each}</div>
        {/if}
        {#if Object.keys(handValues).length}
          <details class="poker-values"><summary>POKER HAND VALUES · BASE CHIPS × MULT</summary>
          <div class="hand-values">
            {#each Object.entries(handValues) as [name, values]}
              {@const level = Array.isArray(values) ? values[0] : null}
              {@const chips = Array.isArray(values) ? values[1] : null}
              {@const mult = Array.isArray(values) ? values[2] : null}
              <div class:active={calcState?.hand_stats?.[name]?.[2] > 0} class="hand-value">
                <span>{name}{#if level != null && level > 1}<small>lvl {level}</small>{/if}</span>
                <b>{chips ?? "—"} × {mult ?? "—"}</b>
              </div>
            {/each}
          </div>
          </details>
        {/if}
        <details class="calculator-settings"><summary>Blind / deck settings</summary>
          {#each [["TheFlint", "The Flint"], ["TheEye", "The Eye"], ["PlasmaDeck", "Plasma Deck"], ["Observatory", "Observatory"]] as [key, label]}
            <label><input type="checkbox" checked={Boolean(calcOptions[key])} onchange={(event) => updateCalculator({ options: { ...calcOptions, [key]: event.currentTarget.checked } })}/>{label}</label>
          {/each}
        </details>
        <p class="calculator-caveat">UI estimate, not a live-game prediction. Uses the upstream calculator unchanged; its own unsupported cases still apply. Hidden card bonuses, missing joker state and other blind effects may differ. Nothing here plays a hand or changes training rewards.</p>
      </aside>
      </div>
      <div class="inspector-content" hidden={inspector !== "inventory"}>
        <p class="calculator-help">Recorded inventory for this frame. Deck composition is not draw order.</p>
        <details><summary>Owned vouchers · {ownedVouchers.length}</summary><div class="offer-rack">{#each ownedVouchers as item, index}{@render inventoryCard(item, index, "owned")}{:else}<p class="empty-slot">No owned vouchers recorded.</p>{/each}</div></details>
        <details><summary>Jokers · {jokers.length}</summary><div class="offer-rack">{#each jokers as item, index}{@render inventoryCard(item, index, "joker")}{:else}<p class="empty-slot">No jokers recorded.</p>{/each}</div></details>
        <details><summary>Consumables · {consumables.length}</summary><div class="offer-rack">{#each consumables as item, index}{@render inventoryCard(item, index, "consumable")}{:else}<p class="empty-slot">No consumables recorded.</p>{/each}</div></details>
        {#if actionConsumable}<details open><summary>Consumable used this turn · PRE-ACTION</summary><div class="offer-rack">{#each consumablesForView as item, index}{@render inventoryCard(item, index, "consumable")}{/each}</div></details>{/if}
        <details open={inventoryFocus === "deck"}><summary>Deck composition · {deck.length} recorded cards</summary><div class="offer-rack">{#each deck as card, index}{@render inventoryCard(card, index, "deck")}{:else}<p class="empty-slot">No deck cards recorded.</p>{/each}</div></details>
        <details open={inventoryFocus === "discard"}><summary>Discard pile · {discardCount ?? "not recorded"}</summary><div class="offer-rack">{#each discard as card, index}{@render inventoryCard(card, index, "discard")}{:else}<p class="empty-slot">No discarded cards recorded for this frame.</p>{/each}</div></details>
        <details><summary>Poker hand levels & history · current state</summary>
          {#if recordedHands.length}
            <div class="hand-history"><table>
              <caption>Recorded poker hands · current frame</caption>
              <thead><tr><th scope="col">Hand</th><th scope="col">Level</th><th scope="col">Chips</th><th scope="col">Mult</th><th scope="col">Played total</th><th scope="col">This round</th></tr></thead>
              <tbody>{#each recordedHands as hand}<tr><th scope="row">{hand.name}</th><td>{hand.level ?? "—"}</td><td class="history-chips">{hand.chips == null ? "—" : chips(hand.chips)}</td><td class="history-mult">{hand.mult ?? "—"}</td><td>{hand.played ?? "—"}</td><td>{hand.round ?? "—"}</td></tr>{/each}</tbody>
            </table></div>
          {:else}<p class="empty-slot">No poker hand levels or history recorded.</p>{/if}
          <details><summary>Recorded data</summary><pre>{JSON.stringify({ hand_values: latest.hand_values, hand_stats: latest.hand_stats }, null, 2)}</pre></details>
        </details>
      </div>
      <div class="inspector-content" hidden={inspector !== "trace"}>
        <details open><summary>Complete frame state · {activeFrame?.index < 0 ? "initial" : "post-action"}</summary><pre>{JSON.stringify(latest, null, 2)}</pre></details>
        <details><summary>Action & input state</summary><pre>{JSON.stringify({ action: activeAction, before: previousState }, null, 2)}</pre></details>
        <details><summary>Reward events · entire episode, not frame-aligned</summary><pre>{JSON.stringify(rewardEvents, null, 2)}</pre></details>
      </div>
    </div>
    <footer><span>{latestReward ? "Latest episode reward · " + (latestReward.label || "checkpoint") + " · " + Number(latestReward.reward || 0).toFixed(3) : "Frame " + (framePosition + 1) + " / " + flatFrames.length}</span><span class="art-credit">Art & scoring: <a href="https://github.com/EFHIII/balatro-calculator" target="_blank" rel="noreferrer">EFHIII</a> · Font: <a href="https://managore.itch.io/m6x11" target="_blank" rel="noreferrer">Daniel Linssen</a></span></footer>
  {:else}<div class="empty-section">No structured Balatro state found.</div>{/if}
</section>

<style>
  @font-face { font-family: "BalatroCalculatorPixel"; src: url("data:font/ttf;base64,") format("truetype"); font-display: swap; }
  .balatro-viewer { container-type: inline-size; color: #f5f6f7; background: #3a5055; border: 3px solid #56666b; border-radius: 10px; margin: 10px 0; font: 17px/1.2 "BalatroCalculatorPixel", ui-monospace, monospace; overflow: visible; text-shadow: 0 1px #0003; }
  .balatro-viewer button, .balatro-viewer input { font: inherit; }
  .balatro-viewer button, .balatro-viewer summary { cursor: pointer; }
  .balatro-viewer button:disabled { cursor: default; opacity: .45; }
  .balatro-viewer button:focus-visible, .balatro-viewer input:focus-visible, .balatro-viewer summary:focus-visible { outline: 3px solid #f3b958; outline-offset: 3px; }
  .balatro-viewer pre { white-space: pre-wrap; overflow-wrap: anywhere; font: 12px/1.5 ui-monospace, monospace; max-height: 340px; overflow-y: auto; text-shadow: none; }
  .viewer-header { display: flex; align-items: center; gap: 12px; padding: 8px 12px; background: #273337; border-radius: 7px 7px 0 0; }
  .replay-brand { display: flex; align-items: baseline; gap: 10px; } .replay-brand b { font-size: 23px; letter-spacing: 2px; font-weight: normal; } .replay-brand small, .replay-meta { color: #b6c5c9; font-size: 12px; }
  .replay-meta { margin-left: auto; } .run-badge { color: #f6c763; text-transform: uppercase; font-size: 14px; }
  .replay-notice { margin: 0; padding: 8px 12px; color: #f6c763; font-size: 13px; }
  .replay-controls { display: flex; align-items: center; gap: 9px; padding: 8px 12px; background: #303e43; border-bottom: 2px solid #263338; }
  .replay-controls button, .inspector-heading button { border: 0; border-radius: 4px; color: #fff; background: #59696e; padding: 5px 10px; }
  .game-layout { display: grid; grid-template-columns: 182px minmax(0, 1fr); }
  .game-hud { padding: 10px; background: #3a4549; border-right: 3px solid #263337; display: flex; flex-direction: column; gap: 8px; }
  .blind-hud { border: 2px solid #202c31; border-radius: 8px; background: #273438; box-shadow: 0 3px #202b2f; text-align: center; overflow: hidden; }
  .blind-hud h3 { margin: 0; padding: 7px 4px; background: #56676f; font-size: 23px; line-height: 1; font-weight: normal; text-transform: capitalize; }
  .blind-hud p { margin: 6px; font-size: 14px; }
  .target { display: flex; align-items: center; justify-content: center; gap: 6px; padding: 9px 5px; } .target > div { min-width: 0; }
  .target small { display: block; font-size: 12px; color: #d5e0e4; } .target strong { display: block; color: #fe5f55; font-size: 31px; font-weight: normal; overflow-wrap: anywhere; }
  .blind-chip { display: grid; place-items: center; flex: 0 0 34px; height: 34px; border: 5px double #89b8d3; border-radius: 50%; background: #337aa4; font-size: 27px; box-shadow: 0 2px #142f41; }
  .round-score, .remaining-score { display: flex; align-items: center; gap: 6px; justify-content: space-between; padding: 6px 7px; border-radius: 6px; background: #253339; } .round-score { border: 2px solid #69808b; }
  .round-score small, .remaining-score small { font-size: 12px; max-width: 80px; } .round-score strong { font-size: 28px; font-weight: normal; overflow-wrap: anywhere; min-width: 0; } .remaining-score strong { font-size: 20px; font-weight: normal; color: #f3b958; overflow-wrap: anywhere; min-width: 0; }
  .score-info { font-size: 12px; color: #ccd6dc; } .score-info p { margin: 5px 0; line-height: 1.3; }
  .hud-calculation { background: #202e33; border: 2px solid #74838a; border-radius: 7px; padding: 7px; text-align: center; }
  .hud-calculation > small { display: block; color: #bcc9cf; font-size: 11px; } .hud-calculation > b { display: block; font-weight: normal; font-size: 16px; margin-top: 6px; } .hud-calculation > strong { display: block; font-weight: normal; color: #f3b958; overflow-wrap: anywhere; }
  .resource-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
  .recorded-score { display: grid; gap: 3px; padding-bottom: 8px; margin-bottom: 7px; border-bottom: 1px solid #74838a; } .recorded-score small { font-size: 11px; color: #bdcfc7; } .recorded-score b { font-weight: normal; } .recorded-score strong { font-weight: normal; color: #f3b958; font-size: 25px; overflow-wrap: anywhere; }
  .calculator-input-link { font-size: 12px; color: #f3b958; background: transparent; border: 0; padding: 4px; }
  .playing-card.recorded-discard { transform: translateY(-9px); outline: 3px solid #fe5f55; outline-offset: 2px; } .playing-card.recorded-discard.selected { outline-color: #f3b958; }
  .discarded-mark { position: absolute; bottom: 4px; left: 4px; padding: 1px 4px; background: #bf4741; color: white; border-radius: 3px; font-size: 17px; }
  .discard-peek { border: 1px solid #b88780; border-radius: 5px; padding: 6px; color: #ffe2d9; background: #734c45; font-size: 13px; }
  .resource-grid > div { display: grid; justify-items: center; padding: 4px; background: #26363d; border: 2px solid #586f7b; border-radius: 6px; }
  .resource-grid small { font-size: 14px; } .resource-grid strong { color: #f3b958; font-size: 32px; font-weight: normal; } .resource-grid em { font-size: 16px; font-style: normal; color: #e0e3df; }
  .resource-grid .hands-resource strong { color: #009dff; } .resource-grid .discards-resource strong { color: #fe5f55; }
  .resource-grid .money-resource { grid-column: 1 / -1; } .money-resource small { display: none; }
  .ante-note { font-size: 12px; color: #f3b958; margin: 0; }
  .hud-buttons { display: grid; grid-template-columns: 1fr 1fr; gap: 7px; margin-top: auto; padding-bottom: 3px; }
  .hud-buttons button { color: #fff; padding: 8px 4px; border: 0; border-radius: 6px; box-shadow: 0 3px #202d33; }
  .run-info-button { background: #df625b; } .settings-button { background: #aa772f; } .trace-button { background: #556971; grid-column: 1 / -1; }
  .game-table { min-width: 0; display: flex; flex-direction: column; padding: 10px 14px 8px; background: radial-gradient(ellipse at 50% 40%, #41665c 0%, #345651 65%, #2d4948 100%); }
  .top-racks { display: grid; grid-template-columns: minmax(0, 1fr) minmax(130px, .32fr); gap: 16px; align-items: start; }
  .jokers-zone, .consumable-zone { min-width: 0; }
  .section-label { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 4px; padding: 4px 0 6px; color: #d2e0d9; font-size: 14px; } .section-label small { color: #b6cbc3; font-size: 12px; }
  .phase-stage { flex: 1; padding: 12px 0; min-height: 110px; }
  .phase-heading { display: flex; justify-content: space-between; align-items: center; gap: 10px; } .phase-heading h4 { margin: 2px 0; font-size: 26px; font-weight: normal; } .phase-heading > span { color: #f3b958; font-size: 15px; }
  .shop-layout { display: grid; grid-template-columns: 1fr 1fr; gap: 15px; }
  .mini-rack, .offer-rack { display: flex; align-items: start; flex-wrap: wrap; gap: 10px; } .mini-rack { justify-content: center; gap: 6px; } .pack-rack { justify-content: center; padding: 12px 0; }
  .inventory-card { width: 82px; position: relative; flex: 0 0 auto; text-align: center; }
  .inventory-card > summary { display: grid; justify-items: center; list-style: none; gap: 3px; }
  .inventory-card > summary::-webkit-details-marker { display: none; }
  .inventory-art { display: block; width: 66px; height: 88px; filter: drop-shadow(2px 3px 1px #0005); }
  .inventory-symbol { display: grid; place-items: center; width: 100%; height: 100%; background: #506f81; border: 3px double #d4dedc; border-radius: 5px; box-sizing: border-box; font-size: 38px; }
  .inventory-card[data-kind="pack"] .inventory-symbol { background: #a46e37; } .inventory-card[data-kind="voucher"] .inventory-symbol, .inventory-card[data-kind="owned"] .inventory-symbol { background: #887447; }
  .inventory-name { font-size: 14px; line-height: 1; overflow-wrap: anywhere; } .inventory-card summary > small { color: #f3b958; font-size: 12px; }
  .inventory-description { position: absolute; top: 100%; left: 0; width: min(240px, 65vw); z-index: 40; padding: 10px; border: 3px solid #cbd5d8; border-radius: 8px; background: #35474b; box-shadow: 0 4px #1c2d32; text-align: left; box-sizing: border-box; }
  .inventory-description p { font-size: 15px; } .inventory-description pre { max-height: 150px; }
  .mini-rack .inventory-description, .offer-rack .inventory-card:last-child .inventory-description { right: 0; left: auto; }
  .empty-slot { font-size: 14px; color: #bdd0c6; padding: 12px 0; }
  .table-watermark { display: grid; justify-items: center; padding: 28px 0; font-size: 36px; letter-spacing: 5px; color: #ffffff25; } .table-watermark small { letter-spacing: 0; font-size: 14px; color: #bacfc3; }
  .end-state { text-align: center; padding: 12px; } .end-state h4 { font-size: 30px; color: #ff978b; margin: 0; } .end-state p { font-size: 15px; }
  .hand-zone { margin-top: auto; min-width: 0; border-top: 1px solid #aec4b536; padding-top: 6px; } .hand-zone.historical { border-top-color: #c9ab59; }
  .historical-note { margin: 5px 0; color: #ecd298; font-size: 12px; line-height: 1.25; }
  .table-actions { display: flex; gap: 10px; align-items: center; } .table-actions > small { font-size: 12px; color: #bccfc6; max-width: 100px; }
  .deck-peek { display: flex; align-items: center; gap: 8px; margin-left: auto; padding: 0; border: 0; background: none; color: #e2e9e3; font-size: 14px; }
  .deck-back { width: 33px; height: 43px; display: grid; place-items: center; font-size: 28px; color: #eddfca; border: 3px double #ecd9c6; border-radius: 4px; background: repeating-linear-gradient(45deg, #a84f45 0 3px, #bf6957 3px 5px); box-shadow: 2px 2px #d9c8b2, 3px 3px #425046; }
  .inspector-panel { padding: 10px 14px; background: #303e43; border-top: 2px solid #698088; }
  .inspector-panel[hidden], .inspector-content[hidden] { display: none; }
  .inspector-heading { display: flex; align-items: center; justify-content: space-between; margin-bottom: 8px; font-size: 16px; } .inspector-heading b { font-weight: normal; color: #f3b958; }
  .inspector-content > details { border-top: 1px solid #566970; padding: 8px 0; } .inspector-content summary { font-size: 16px; } .inspector-content > details > .offer-rack { margin-top: 10px; }
  .hand-history { overflow-x: auto; margin: 10px 0; }
  .hand-history table { width: 100%; border-collapse: collapse; text-align: right; white-space: nowrap; }
  .hand-history caption { text-align: left; color: #b6c5c9; padding-bottom: 8px; }
  .hand-history th, .hand-history td { padding: 6px 10px; border-bottom: 1px solid #566970; font-weight: normal; }
  .hand-history th:first-child { text-align: left; }
  .history-chips { color: #89c8ff; } .history-mult { color: #ff9b9b; }
  .chip-note, .calculator-help { color: #d0d9de; font-size: 14px; margin: 6px 0 9px; line-height: 1.3; }
  .blind-strip { display: flex; gap: 6px; padding: 12px; overflow-x: auto; background: #293438; }
  .blind-tab { display: flex; flex: 0 0 auto; gap: 8px; align-items: center; padding: 8px 12px; border: 0; border-radius: 6px; box-shadow: 0 3px #20282c; color: #d9dfe5; background: #4f6367; text-align: left; }
  .blind-tab.active { background: #a3acb9; color: #19282d; box-shadow: 0 3px #686e78; } .blind-tab b { display: block; font-weight: normal; text-transform: uppercase; } .blind-tab small { display: block; font-size: 13px; } .tab-index { opacity: .65; }
  .turn-strip { display: flex; gap: 6px; align-items: center; padding: 12px; overflow-x: auto; font-size: 14px; } .turn-dot { flex: 0 0 auto; min-width: 26px; height: 26px; border: 0; border-radius: 5px; color: #dce4ea; background: #29383d; }
  .turn-dot.active { color: #263136; background: #f3b958; }
  .action-banner { display: flex; flex-wrap: wrap; gap: 10px; margin: 0 12px 12px; padding: 8px 12px; border-radius: 6px; background: #29383d; color: #dce4ea; font-size: 16px; }
  .action-method { color: #f3b958; text-transform: uppercase; } .action-discard .action-method { color: #ff978b; } .action-use .action-method { color: #c4aeff; }
  .skip-result { margin: 0 12px 12px; padding: 12px; border: 2px solid #eac058; border-radius: 8px; background: #374244; }
  .skip-result-title { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 8px; color: #eac058; } .skip-result-title span { font-size: 14px; }
  .skip-result-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 12px; margin-top: 10px; } .skip-result-grid div { display: grid; gap: 4px; } .skip-result-grid small { color: #bfc7d5; font-size: 14px; } .skip-result-grid strong { font-weight: normal; }
